# 模型管理：保存连入的模型到模型库；按多选输出库中模型
import os
import datetime
import json as _json

model_dir = {{folder}}
selected_models = {{models}}


def _items(value):
    if value is None:
        return []
    if isinstance(value, (list, tuple)):
        return [item for item in value if item is not None]
    return [value]


if not model_dir or not os.path.isdir(model_dir):
    raise RuntimeError('请先选择有效的模型库目录')

try:
    _model_value = model
except NameError:
    _model_value = None

# ── 1. 保存连入的模型 ────────────────────────
_saved_names = []
for _index, _item in enumerate(_items(_model_value), start=1):
    if not isinstance(_item, dict):
        raise RuntimeError('第 ' + str(_index) + ' 个模型必须是 JSON 对象（dict）')
    _type = str(_item.get('type', 'model'))
    _target = str(_item.get('target', 'unknown'))
    _base = _type + '_' + _target
    _candidate = os.path.join(model_dir, _base + '.json')
    _number = 1
    while os.path.exists(_candidate):
        _candidate = os.path.join(model_dir, _base + ' (' + str(_number) + ').json')
        _number += 1
    with open(_candidate, 'w', encoding='utf-8') as _file:
        _json.dump(_item, _file, ensure_ascii=False, indent=2)
    _saved_names.append(os.path.basename(_candidate))

# ── 2. 读取模型库（含刚保存的） ──────────────
_available = {}
for _name in sorted(os.listdir(model_dir)):
    if not _name.lower().endswith('.json'):
        continue
    _key = _name[:-5]  # 去掉 .json 扩展名
    try:
        with open(os.path.join(model_dir, _name), encoding='utf-8') as _file:
            _available[_key] = _json.load(_file)
    except Exception:
        continue  # 不是合法 JSON 的跳过

# ── 3. 按多选输出选中模型 ────────────────────
_result = []
if isinstance(selected_models, (list, tuple)) and len(selected_models) > 0:
    _missing = [key for key in selected_models if key not in _available]
    if _missing:
        raise RuntimeError('模型库中找不到：' + '、'.join(_missing))
    _result = [_available[key] for key in selected_models]

_log = []
if _saved_names:
    _log.append('已保存 ' + str(len(_saved_names)) + ' 个模型：' + '、'.join(_saved_names))
_log.append('模型库共 ' + str(len(_available)) + ' 个模型，本次输出 ' + str(len(_result)) + ' 个')
print('\n'.join(_log))

return _result
